use zkc::oracle
def f(domain: nat) -> nat:
    oracle::rows(domain)

def f(x: nat) -> nat:
    // A comment does not form a suite.
    x

section <F: Field>:
    def f(x: F) -> F:
        x

local def f(x: Pair) -> Pair:
    (a, b) = unpack(x)
    return (b, a)

def f(x: nat) -> nat:
    if x > 0:
        x
    else:
        0

def f(x: nat) -> nat:
    g(
        x, // ) > ignored
        1
    )

def f(x: F) -> F:
    value = guard(x)
    value

def f(x: nat) -> nat:
    x
        + 1

impl Concrete<F: Field>: Checkable<F>:
    def check(x):
        x

with <F: Field>:
    def zero() -> F:
        0
